#!/usr/bin/env bash
# Every colour comes from res/values/jetons.xml, generated by Synseria-Design: fails if that file was edited by
# hand, or if a colour is written anywhere else. A colour that is data, not design (a picture's, EDF's Tempo
# days), says so with "off-palette:" and its reason on its own line.
[ -n "${BASH_VERSION:-}" ] || exec bash "$0" "$@"
set -euo pipefail
cd "$(dirname "$0")/../launcher/app/src/main"
tokens=res/values/jetons.xml
want=$(sed -n 3p "$tokens" | sed -E 's/.*contenu ([0-9a-f]+).*/\1/')
got=$(tail -n +4 "$tokens" | shasum -a 256 | cut -c1-16)
if [ "$want" != "$got" ]; then
  echo "$tokens was edited by hand: change Synseria-Design, then sh propager.sh Synema" >&2
  exit 1
fi
colour='#[0-9A-Fa-f]{3,8}\b|0x[0-9A-Fa-f]{6,8}\b|Color\.(parseColor|argb|rgb|valueOf|WHITE|BLACK|RED|GREEN|BLUE|YELLOW|GRAY|DKGRAY|LTGRAY|CYAN|MAGENTA)\b|@android:color/[a-z_]+'
# What is not a colour, taken out of a line before looking: a numeric entity (&#160;), the transparent resource, and
# the masks of a bit expression that keep (& 0x00FFFFFF) or set (| 0xB3000000) an alpha, whichever side the operator is.
mask='&#[0-9]+;|@android:color/transparent|&[[:space:]]*0x(00)?FFFFFF\b|[&|][[:space:]]*0x[0-9A-Fa-f]{2}000000\b|\b0x[0-9A-Fa-f]{2}000000[[:space:]]*[&|]'
found=$(grep -rnEI "$colour" java res --include='*.java' --include='*.xml' | grep -v "^$tokens:" | while IFS=: read -r file line rest; do
  bare=$(MASK="$mask" perl -pe 's~$ENV{MASK}~~g' <<<"$rest")
  grep -qE "$colour" <<<"$bare" || continue
  [[ "$rest" == *off-palette:* ]] || echo "$file:$line:$rest"
done)
if [ -n "$found" ]; then
  echo "colours outside jetons.xml (use @color/syn_*, or mark data colours off-palette: <why>):" >&2
  echo "$found" >&2
  exit 1
fi
# The accent is the user's choice: it is read from the theme (?attr/syn_primaire*, Tokens.primary*), never the fixed Azur default.
fixed=$(grep -rnE '@color/syn_primaire|R\.color\.syn_primaire' java res --include='*.java' --include='*.xml' | grep -v "^$tokens:" || true)
if [ -n "$fixed" ]; then
  echo "primary accent fixed to Azur (use ?attr/syn_primaire*, or Tokens.primary / Tokens.primaryInk in code):" >&2
  echo "$fixed" >&2
  exit 1
fi
